  "inlineSchema": "generator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// Setor é informativo (de onde a pessoa é); quem manda nas permissões\n// é o perfil de acesso (PermissionProfile) aplicado ao usuário.\nenum Sector {\n  SOCIETARIO\n  FISCAL\n  CONTABIL\n  DP\n  CONTROLADORIA\n  COMERCIAL\n  ADMINISTRATIVO\n}\n\nenum CertMedia {\n  FILE\n  CARD\n}\n\n// Perfil de acesso: um \"padrão de configuração\" reutilizável.\n// rules é um mapa módulo -> nível (\"none\" | \"view\" | \"edit\"),\n// ex.: { \"empresas\": \"view\", \"certificados\": \"view\", \"acessos\": \"edit\" }.\n// admin = gerencia equipe, perfis e políticas do cofre (e edita tudo).\nmodel PermissionProfile {\n  id        String   @id @default(uuid())\n  name      String   @unique\n  admin     Boolean  @default(false)\n  rules     Json     @default(\"{}\")\n  users     User[]\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel User {\n  id           String             @id @default(uuid())\n  name         String\n  email        String             @unique\n  passwordHash String\n  sector       Sector             @default(ADMINISTRATIVO)\n  profileId    String?\n  profile      PermissionProfile? @relation(fields: [profileId], references: [id], onDelete: SetNull)\n  createdAt    DateTime           @default(now())\n}\n\n// Grupo econômico: empresas do mesmo dono/rede, agrupadas à mão.\n// Filtrar pelo grupo traz o cofre de todas as empresas dele de uma vez.\nmodel CompanyGroup {\n  id           String        @id @default(uuid())\n  name         String        @unique\n  companies    Company[]\n  certificates Certificate[] // e-CPF (e certificados sem empresa) agrupam direto\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n}\n\n// Empresa (cliente) — dona de um cofre próprio: certificados, acessos,\n// alvarás e outros documentos.\nmodel Company {\n  id           String        @id @default(uuid())\n  cnpj         String        @unique // só dígitos\n  razaoSocial  String\n  groupId      String?\n  group        CompanyGroup? @relation(fields: [groupId], references: [id], onDelete: SetNull)\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n  certificates Certificate[]\n  accesses     Access[]\n  alvaras      Alvara[]\n\n  @@index([groupId])\n}\n\nmodel Certificate {\n  id        String             @id @default(uuid())\n  holder    String\n  document  String\n  type      String\n  media     CertMedia          @default(FILE)\n  issuer    String\n  issuedAt  DateTime\n  expiresAt DateTime\n  password  String\n  fileName  String?\n  fileData  String? // .pfx em base64 — usado quando não há pasta de arquivos\n  filePath  String? // caminho relativo na pasta raiz, quando o .pfx vive em disco\n  notes     String?\n  companyId String?\n  company   Company?           @relation(fields: [companyId], references: [id], onDelete: SetNull)\n  // Grupo direto do certificado — vale quando ele NÃO tem empresa (e-CPF avulso).\n  // Com empresa, o grupo é o dela; este fica nulo. Efetivo = empresa ?? este.\n  groupId   String?\n  group     CompanyGroup?      @relation(fields: [groupId], references: [id], onDelete: SetNull)\n  events    CertificateEvent[]\n  createdAt DateTime           @default(now())\n  updatedAt DateTime           @updatedAt\n  accesses  Access[]\n\n  @@index([groupId])\n}\n\n// Linha do tempo do certificado: cadastro, alterações e observações\n// deixadas pela equipe (\"solicitado renovação\", \"cliente avisado\"…).\nmodel CertificateEvent {\n  id            String      @id @default(uuid())\n  certificateId String\n  certificate   Certificate @relation(fields: [certificateId], references: [id], onDelete: Cascade)\n  kind          String // created | updated | note\n  message       String?\n  userName      String\n  createdAt     DateTime    @default(now())\n\n  @@index([certificateId, createdAt])\n}\n\n// Alvarás e licenças da empresa (funcionamento, sanitário, bombeiros…).\n// Os dados são digitados manualmente; o PDF do documento fica guardado.\n// Sem data de vencimento = alvará permanente.\nmodel Alvara {\n  id        String        @id @default(uuid())\n  name      String // ex.: Alvará de Funcionamento\n  number    String? // número/protocolo do documento\n  issuer    String? // órgão emissor (prefeitura, corpo de bombeiros…)\n  issuedAt  DateTime?\n  expiresAt DateTime?\n  fileName  String?\n  fileData  String? // PDF em base64 — usado quando não há pasta de arquivos\n  filePath  String? // caminho relativo na pasta raiz, quando o PDF vive em disco\n  notes     String?\n  companyId String?\n  company   Company?      @relation(fields: [companyId], references: [id], onDelete: SetNull)\n  events    AlvaraEvent[]\n  createdAt DateTime      @default(now())\n  updatedAt DateTime      @updatedAt\n}\n\n// Linha do tempo do alvará: cadastro, alterações e observações da\n// equipe (\"foi cobrado do cliente\", \"renovação em andamento\"…).\nmodel AlvaraEvent {\n  id        String   @id @default(uuid())\n  alvaraId  String\n  alvara    Alvara   @relation(fields: [alvaraId], references: [id], onDelete: Cascade)\n  kind      String // created | updated | note\n  message   String?\n  userName  String\n  createdAt DateTime @default(now())\n\n  @@index([alvaraId, createdAt])\n}\n\n// Acessos a sites (prefeituras, portais, sistemas) com tutorial em Markdown.\n// Quando o login é por certificado digital, aponta pro certificado do cofre\n// e a senha do acesso passa a ser a do certificado.\nmodel Access {\n  id            String       @id @default(uuid())\n  name          String // ex.: Prefeitura de Blumenau\n  url           String\n  loginType     String // CNPJ, CPF, E-mail, Usuário, Certificado digital, Outro\n  loginValue    String\n  password      String\n  certificateId String?\n  certificate   Certificate? @relation(fields: [certificateId], references: [id], onDelete: SetNull)\n  companyId     String?\n  company       Company?     @relation(fields: [companyId], references: [id], onDelete: SetNull)\n  notes         String?\n  tutorial      String? // markdown; imagens via /api/images/{id}\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n}\n\nmodel TutorialImage {\n  id        String   @id @default(uuid())\n  mime      String\n  data      String? // base64 — usado quando não há pasta de arquivos\n  filePath  String? // caminho relativo na pasta raiz, quando a imagem vive em disco\n  createdAt DateTime @default(now())\n}\n\n// Configuração global do cofre (linha única) — definida por um admin.\n// O bloqueio é geral: bloqueou, travou para todos.\nmodel VaultConfig {\n  id          Int     @id @default(1)\n  alertDays   Int     @default(45) // janela de \"vencendo\" para o cofre inteiro\n  locked      Boolean @default(false)\n  lockPinHash String? // bcrypt do PIN de bloqueio (só admins conhecem)\n  autoLock    Boolean @default(true) // sair por inatividade (política p/ todos)\n  lockMinutes Int     @default(15)\n  storageRoot String? // pasta raiz (na rede) onde os arquivos ficam; null = no banco\n}\n",
